    #[test]
    fn token_derive_bound_and_variant_shapes() {
        assert_token_derives::<Token>();
        let _ = [Token::Plus, Token::Minus, Token::RegexPrefix, Token::Eof,
                 Token::QuotedString(String::new()), Token::Word(String::new())];
