Write the test(s). Proves from_terms() builds required/excluded/scored by independently iterating terms.iter().enumerate() three times, each filtering on a distinct Modifier variant and collecting matching indices via .map(|(i, _)| i) with no re-sorting -- each Vec<usize> preserves the relative order its matching terms had in the original terms Vec. A 6-term mixed input verifies required=[1,3], excluded=[2,5], scored=[0,4] exactly, and that the union of all three category index-vecs, sorted, is exactly 0..6 -- every index appears in exactly one category, never zero, never more than one. Run: `cat > /Users/gabe/Projects/monokl/crates/monokl/src/query/plan.rs <<'RUSTEOF'
use super::parser::{Modifier, ParsedTerm};

#[derive(Debug, Clone)]
pub struct QueryPlan {
    pub terms: Vec<ParsedTerm>,
    pub required: Vec<usize>,
    pub excluded: Vec<usize>,
    pub scored: Vec<usize>,
}

impl QueryPlan {
    pub fn from_terms(terms: Vec<ParsedTerm>) -> Self {
        let required: Vec<usize> = terms.iter().enumerate()
            .filter(|(_, t)| t.modifier == Modifier::Required)
            .map(|(i, _)| i).collect();
        let excluded: Vec<usize> = terms.iter().enumerate()
            .filter(|(_, t)| t.modifier == Modifier::Excluded)
            .map(|(i, _)| i).collect();
        let scored: Vec<usize> = terms.iter().enumerate()
            .filter(|(_, t)| t.modifier == Modifier::Optional)
            .map(|(i, _)| i).collect();
        Self { terms, required, excluded, scored }
    }

    pub fn is_empty(&self) -> bool { self.terms.is_empty() }

    pub fn search_patterns(&self) -> Vec<&str> {
        self.required.iter().chain(self.scored.iter())
            .map(|&i| self.terms[i].pattern.as_str())
            .collect()
    }
}

